package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ServiceCertificateIdentity;import jakarta.servlet.http.HttpServletRequest;import java.math.BigInteger;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.util.function.ThrowingSupplier;
/** Original adapter can report an unresolved attempt without manufacturing a provider receipt or releasing funds. */
public final class FormalInvocationUncertainty {
 private final JdbcTemplate db;private final ServiceCertificateIdentity services;private final TenantTransaction transactions;private final FormalInvocationSchema schema;
 public FormalInvocationUncertainty(DataSource data,ServiceCertificateIdentity services,TenantTransaction transactions,FormalInvocationSchema schema){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.services=services;this.transactions=transactions;this.schema=schema;}
 public JsonNode record(HttpServletRequest http,String tenant,String actor,String invocation,String attempt)throws Exception{
  for(String id:List.of(tenant,actor,invocation,attempt))WireValues.uuid(id);var identity=services.require(http);var epochs=one(db.query("SELECT auth_epoch,governance_epoch FROM tenant WHERE tenant_id=? LIMIT 2",(r,n)->new TenantWatermarks(r.getBigDecimal(1).toBigIntegerExact(),r.getBigDecimal(2).toBigIntegerExact()),tenant));
  try(var scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ZERO,epochs.authEpoch(),epochs.governanceEpoch()))){return transactions.execute(ignored->ThrowingSupplier.of(()->{
   var binding=schema.parse(one(db.query("SELECT JSON_OBJECT('project_id',i.project_id,'created_by',i.created_by,'classification',i.classification,'actual_send_manifest',i.actual_send_manifest,'actual_send_sha256',i.actual_send_sha256,'input_sha256',i.input_sha256,'attempt_id',a.attempt_id,'request_sha256',a.request_sha256,'service_uri',a.service_uri,'certificate_sha256',a.certificate_sha256,'trust_revision',a.trust_revision,'lease_generation',CAST(a.lease_generation AS CHAR),'status',i.status,'settlement_status',i.settlement_status) FROM invocation i JOIN formal_invocation_attempt a ON a.tenant_id=i.tenant_id AND a.invocation_id=i.invocation_id WHERE i.tenant_id=? AND i.invocation_id=? AND i.created_by=? AND a.attempt_id=? AND i.dispatch_generation=1 AND a.dispatch_generation=1 AND a.lease_generation=i.lease_generation AND a.input_sha256=i.input_sha256 AND a.created_by=i.created_by AND a.schema_version='1.0.0' AND a.schema_manifest_sha256=? LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),tenant,invocation,actor,attempt,schema.manifestSha256())));
   if(!identity.serviceUri().equals(t(binding,"service_uri"))||!identity.certificateSha256().equals(t(binding,"certificate_sha256"))||!identity.trustRevision().equals(t(binding,"trust_revision")))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);FormalInvocationDispatch.verifyEvidence(db,schema,tenant,invocation,binding);
   var old=db.query("SELECT receipt_json,receipt_sha256 FROM formal_invocation_uncertainty WHERE tenant_id=? AND invocation_id=? AND attempt_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2)),tenant,invocation,attempt);if(old.size()>1)bad();if(!old.isEmpty())return verify(tenant,actor,invocation,attempt,binding,old.get(0).get(0),old.get(0).get(1));
   if(!db.query("SELECT audit_id FROM audit_event WHERE tenant_id=? AND subject_id=? AND action='model.invocation_unknown' AND request_id=? LIMIT 2",(r,n)->r.getString(1),tenant,actor,attempt).isEmpty())bad();
   if(!Set.of("DISPATCHING","IN_FLIGHT","UNKNOWN","CANCEL_REQUESTED").contains(t(binding,"status"))||!"PENDING".equals(t(binding,"settlement_status")))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
   var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));String project=t(binding,"project_id"),classification=t(binding,"classification");var receipt=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("invocation_id",invocation).put("dispatch_attempt_id",attempt).put("kind","TRANSPORT_OUTCOME_UNKNOWN").put("status","UNKNOWN").put("settlement_status","PENDING").put("reservations_released",false).put("created_at",now.toString());String raw=schema.canonical(receipt),hash=schema.hash(receipt);
   if(db.update("UPDATE invocation SET status='UNKNOWN',revision=revision+1,updated_at=? WHERE tenant_id=? AND invocation_id=? AND settlement_status='PENDING' AND status IN ('DISPATCHING','IN_FLIGHT','UNKNOWN','CANCEL_REQUESTED')",now,tenant,invocation)!=1)bad();
   changed(db.update("INSERT INTO formal_invocation_uncertainty(tenant_id,project_id,invocation_id,attempt_id,receipt_json,receipt_sha256,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'1.0.0',?,?,?,?)",tenant,project,invocation,attempt,raw,hash,schema.manifestSha256(),actor,now,classification));changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,'model.invocation_unknown',?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",tenant,project,UUID.randomUUID().toString(),actor,raw,attempt,invocation,schema.manifestSha256(),actor,now,classification));changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,'model.invocation_unknown',?,?)",tenant,UUID.randomUUID().toString(),attempt,raw,now));var fresh=services.require(http);if(!identity.serviceUri().equals(fresh.serviceUri())||!identity.certificateSha256().equals(fresh.certificateSha256())||!identity.trustRevision().equals(fresh.trustRevision()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);return verify(tenant,actor,invocation,attempt,binding,raw,hash);
  }).get());}
 }
 private JsonNode verify(String tenant,String actor,String invocation,String attempt,JsonNode binding,String raw,String hash)throws Exception{var r=schema.parse(raw);if(!schema.hash(r).equals(hash)||!schema.canonical(r).equals(raw)||!invocation.equals(t(r,"invocation_id"))||!attempt.equals(t(r,"dispatch_attempt_id")))bad();if(!"1.0.0".equals(t(r,"schema_version"))||!"TRANSPORT_OUTCOME_UNKNOWN".equals(t(r,"kind"))||!"UNKNOWN".equals(t(r,"status"))||!"PENDING".equals(t(r,"settlement_status"))||!r.required("reservations_released").isBoolean()||r.required("reservations_released").booleanValue()||r.size()!=8)bad();var at=java.time.LocalDateTime.parse(t(r,"created_at"));if(one(db.query("SELECT COUNT(*) FROM formal_invocation_uncertainty WHERE tenant_id=? AND project_id=? AND invocation_id=? AND attempt_id=? AND receipt_json=? AND receipt_sha256=? AND created_by=? AND created_at=? AND classification=? AND schema_version='1.0.0' AND schema_manifest_sha256=?",(rs,n)->rs.getInt(1),tenant,t(binding,"project_id"),invocation,attempt,raw,hash,actor,at,t(binding,"classification"),schema.manifestSha256()))!=1)bad();var a=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND subject_id=? AND created_by=? AND action='model.invocation_unknown' AND result='SUCCESS' AND request_id=? AND trace_id=? AND schema_manifest_sha256=? LIMIT 2",(rs,n)->rs.getString(1),tenant,actor,actor,attempt,invocation,schema.manifestSha256()));var e=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='model.invocation_unknown' LIMIT 2",(rs,n)->rs.getString(1),tenant,attempt));if(!raw.equals(schema.canonical(schema.parse(a)))||!raw.equals(schema.canonical(schema.parse(e))))bad();return r;}
 private static String t(JsonNode n,String k){return n.required(k).textValue();}private static void changed(int n){if(n!=1)bad();}private static <T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)bad();return rows.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
